<script setup lang="ts">
import { reactive, ref } from 'vue'; import { useRouter } from 'vue-router'; import { showToast } from 'vant'; import { createApiClient } from '../api/client'; import { createIdempotencyKey } from '../api/idempotency'
const router = useRouter(); const form = reactive({ origin: '', destination: '', departureAt: '', capacity: 4 as 3 | 4 }); const busy = ref(false); const error = ref('')
async function submit() { error.value = ''; const departure = new Date(form.departureAt); if (!form.origin.trim() || !form.destination.trim()) return error.value = '请填写出发地和目的地'; if (!form.departureAt || Number.isNaN(departure.getTime()) || departure <= new Date()) return error.value = '出发时间必须晚于当前时间'; busy.value = true; try { const trip = await createApiClient().createTrip({ ...form, origin: form.origin.trim(), destination: form.destination.trim(), departureAt: departure.toISOString() }, createIdempotencyKey()); showToast('行程已发布'); await router.replace(`/trips/${trip.id}`) } catch (caught) { error.value = caught instanceof Error ? caught.message : '发布失败' } finally { busy.value = false } }
</script>
<template><main class="page"><div class="eyebrow">发布你的路线</div><h1>让空座位找到同行的人</h1><form class="trip-form" @submit.prevent="submit"><label>出发地<input v-model="form.origin" placeholder="例如：大学城南门" /></label><label>目的地<input v-model="form.destination" placeholder="例如：火车站" /></label><label>出发时间<input v-model="form.departureAt" type="datetime-local" /></label><label>总人数（含你）<select v-model.number="form.capacity"><option :value="3">3 人</option><option :value="4">4 人</option></select></label><p v-if="error" class="form-error" role="alert">{{ error }}</p><button class="primary-button" :disabled="busy">{{ busy ? '发布中…' : '发布行程' }}</button></form></main></template>
